SET search_path=vcm,pg_catalog;
CREATE TABLE decisions(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),kind text NOT NULL CHECK(kind IN('priority','budget','exception','flow')),title text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','coordination_review','leadership_review','direction_required','approved','rejected','returned','postponed','in_execution','closed','escalated')),authority text NOT NULL DEFAULT 'coordination' CHECK(authority IN('coordination','leadership','direction')),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER decision_protect BEFORE INSERT ON decisions FOR EACH ROW EXECUTE FUNCTION protect_object('decision');
CREATE TABLE decision_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),decision_id text NOT NULL REFERENCES decisions(id),version int NOT NULL CHECK(version>0),proposal text NOT NULL,alternatives text,recommendation text,impact text,amount bigint CHECK(amount>=0),requested_by text NOT NULL REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(decision_id,version));
CREATE TRIGGER decision_revision_register BEFORE INSERT ON decision_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('decisions','decision_id');
CREATE TRIGGER decision_revision_immutable BEFORE UPDATE OR DELETE ON decision_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE approval_records(id text PRIMARY KEY,object_id text NOT NULL,revision_id text NOT NULL,kind text NOT NULL CHECK(kind IN('annual_plan','flow','budget','campaign','content','package','institutional')),approved_by text NOT NULL REFERENCES principals(id),reason text NOT NULL CHECK(length(trim(reason))>0),approved_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,FOREIGN KEY(object_id,revision_id) REFERENCES object_revisions(object_id,id),UNIQUE(revision_id,id),CHECK(expires_at IS NULL OR expires_at>approved_at));
CREATE TABLE approval_revocations(approval_id text PRIMARY KEY REFERENCES approval_records(id),revoked_by text NOT NULL REFERENCES principals(id),reason text NOT NULL CHECK(length(trim(reason))>0),revoked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decision_outcomes(id text PRIMARY KEY,decision_revision_id text NOT NULL REFERENCES decision_revisions(id),decided_by text NOT NULL REFERENCES users(principal_id),recorded_by text NOT NULL REFERENCES principals(id),outcome text NOT NULL CHECK(outcome IN('approved','rejected','returned','postponed')),reason text NOT NULL CHECK(length(trim(reason))>0),approved_scope text,budget_basis text,channel text NOT NULL CHECK(channel IN('web','telegram')),delegation_reference text,decided_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operation_mandates(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),plan_revision_id text NOT NULL REFERENCES work_plan_revisions(id),approval_id text NOT NULL REFERENCES approval_records(id),valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,revoked_at timestamptz,CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE mandate_actions(mandate_id text NOT NULL REFERENCES operation_mandates(id),action_class text NOT NULL,limits jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(limits)='object'),PRIMARY KEY(mandate_id,action_class));
CREATE TABLE budget_items(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),name text NOT NULL,planned_amount bigint CHECK(planned_amount>=0),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TRIGGER budget_item_protect BEFORE INSERT ON budget_items FOR EACH ROW EXECUTE FUNCTION protect_object('budget');
CREATE TABLE budget_authorizations(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),decision_revision_id text NOT NULL REFERENCES decision_revisions(id),approval_id text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,FOREIGN KEY(decision_revision_id,approval_id) REFERENCES approval_records(revision_id,id),UNIQUE(project_id,id),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE commitments(id text PRIMARY KEY,project_id text NOT NULL,case_id text NOT NULL,authorization_id text NOT NULL,title text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),reference text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled')),reason text,actor_id text NOT NULL REFERENCES principals(id),version int NOT NULL DEFAULT 1 CHECK(version>0),at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,case_id) REFERENCES project_cases,FOREIGN KEY(project_id,authorization_id) REFERENCES budget_authorizations(project_id,id),UNIQUE(project_id,id));
CREATE TABLE expenses(id text PRIMARY KEY,project_id text NOT NULL,budget_item_id text NOT NULL,concept text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),spent_on date NOT NULL,supplier_id text REFERENCES organizations(id),supplier_label text,reference text,version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,budget_item_id) REFERENCES budget_items(project_id,id),UNIQUE(project_id,id));
CREATE TABLE commitment_expenses(project_id text NOT NULL,commitment_id text NOT NULL,expense_id text NOT NULL UNIQUE,PRIMARY KEY(commitment_id,expense_id),FOREIGN KEY(project_id,commitment_id) REFERENCES commitments(project_id,id),FOREIGN KEY(project_id,expense_id) REFERENCES expenses(project_id,id));
CREATE TABLE forecasts(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),remaining bigint NOT NULL CHECK(remaining>=0),basis jsonb NOT NULL CHECK(jsonb_typeof(basis)='object'),reason text NOT NULL CHECK(length(trim(reason))>0),actor_id text NOT NULL REFERENCES principals(id),version int NOT NULL CHECK(version>0),at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version));
CREATE FUNCTION human_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=vcm,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM principals WHERE id=NEW.approved_by AND kind='human' AND active) THEN RAISE EXCEPTION 'Approval requires active human' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER approval_human BEFORE INSERT ON approval_records FOR EACH ROW EXECUTE FUNCTION human_approval();
CREATE TRIGGER approval_immutable BEFORE UPDATE OR DELETE ON approval_records FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER revocation_immutable BEFORE UPDATE OR DELETE ON approval_revocations FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER outcome_immutable BEFORE UPDATE OR DELETE ON decision_outcomes FOR EACH ROW EXECUTE FUNCTION immutable_row();
ALTER TABLE work_plan_revisions ADD CONSTRAINT plan_revision_project_key UNIQUE(project_id,id);
ALTER TABLE operation_mandates ADD CONSTRAINT mandate_project_plan_fk FOREIGN KEY(project_id,plan_revision_id) REFERENCES work_plan_revisions(project_id,id);
